import json,re
a=json.load(open("docs/sample_articles.json"))
for x in a:
    t=x["headline"]+" "+x["body"]
    f={k:bool(re.search(p,t,re.I)) for k,p in {"AI":r"\bAI\b","health":r"\bhealthcare\b","diag":r"\bdiagnostic\b","startup":r"\bstartup"}.items()}
